    def configure_dc_port(self, target_dn, port_label=None, disconnect_current=None, disconnect_voltage=None,  # noqa: C901
                          reconnect_voltage=None, maintenance_mode=None, power_setting=None, power_schedule_daily=None,
                          power_schedule_weekly=None, timeout=60, detailed_output=False):
        """
        Configure DC port.

        :param str target_dn: Mandatory - DCPORT distName, e.g.:
                              "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/PWRMOD_R-1/DCPORT_R-1"
        :param str port_label: Optional - 1..255 char long.
        :param float diconnect_current: Optional - number ranging from [0.1, 50.0].
        :param float diconnect_voltage: Optional - number ranging from [-58.00, -36.00].
        :param float reconnect_voltage: Optional - number ranging from [-58.00, -36.00].
        :param enum maintenance_mode: Optional - [Disabled, Enabled]
        :param enum power_setting: Optional - [Off, On, Daily, Weekly]
        :param dict power_schedule_daily: Optional - dictionary of On and Off power timing settings.
        :param list power_schedule_weekly: Optional - list of max 7 dict itemes.
        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-configureDCPort.html
        """
        if disconnect_current is not None:
            if disconnect_current < 0.1 or disconnect_current > 50:
                raise_value_error(param="disconnect_current", value=str(disconnect_current),
                                  subpage="tutorial-configureDCPort.html")

        if disconnect_voltage is not None:
            if disconnect_voltage < -58 or disconnect_voltage > -36:
                raise_value_error(param="disconnect_voltage", value=str(disconnect_voltage),
                                  subpage="tutorial-configureDCPort.html")

        if reconnect_voltage is not None:
            if reconnect_voltage < -58 or reconnect_voltage > -36:
                raise_value_error(param="reconnect_voltage", value=str(reconnect_voltage),
                                  subpage="tutorial-configureDCPort.html")

        if maintenance_mode not in ["Disabled", "Enabled"]:
            raise_value_error(param="maintenance_mode",
                              value=str(maintenance_mode),
                              subpage="tutorial-configureDCPort.html")

        if power_setting not in ["Off", "On", "Daily", "Weekly"]:
            raise_value_error(param="power_setting",
                              value=str(power_setting),
                              subpage="tutorial-configureDCPort.html")

        if not isinstance(power_schedule_daily, (dict, type(None))):
            raise TypeError('Parameter power_schedule_daily should be list type not {}'
                            .format(type(power_schedule_daily)))

        if not isinstance(power_schedule_weekly, (list, type(None))):
            raise TypeError('Parameter power_schedule_weekly should be list type not {}'
                            .format(type(power_schedule_weekly)))

        parameters = {"targetDN": target_dn,
                      "portLabel": port_label,
                      "disconnectCurrent": disconnect_current,
                      "disconnectVoltage": disconnect_voltage,
                      "reconnectVoltage": reconnect_voltage,
                      "maintenanceMode": maintenance_mode,
                      "powerSetting": power_setting,
                      "powerScheduleDaily": power_schedule_daily,
                      "powerScheduleWeekly": power_schedule_weekly}

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure("configureDCPort", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

