    def generate_fault(self, sender, receiver, message, timeout=10, sic_message_id=None):
        """
        Generate fault

        :param int sender: Sender SIC address.
        :param int receiver: Receiver SIC address.
        :param SicMessage: Fault specific message.
        :param int timeout: (optional) Timeout for the operation.
        :param int sic_message_id: (optional) Custom SiC message id.
        """
        if sic_message_id:
            id = sic_message_id
        else:
            id = message.id

        parameters = {
            "id": id,
            "sender": sender,
            "receiver": receiver,
            "payload": message.payload
        }
        self._api_client.execute_procedure("generateFault", parameters, timeout)

    def reset_unit(self, dist_name, reset_type='Soft', force_radio_reset=None, timeout=60, detailed_output=False,
                   graceful_cell_shutdown=None):
        """
        Preform unit reset procedure.

        :param dist_name: Dist name of unit to reset which is runtime view dist name like:
                          /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1/GNSSE_R-1.
        :param str reset_type: (Optional) can be `Soft` or `Hard`
                               If no value is provided, defaults to Hard. If unit is PWRMOD or DCPORT, this value always is Soft.
        :param bool force_radio_reset: (Optional) can be set to True or False.
        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param bool graceful_cell_shutdown: (Optional) - Defaults to False, it is not applicable to ALD/GNSSE/GNSSI.
        :return Union[list,dict]: Unit reset status, or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """
        reset_type = reset_type.title()

        parameters = {"id": dist_name, 'resetType': reset_type}
        if force_radio_reset is not None:
            parameters['forceRadioReset'] = force_radio_reset

        if graceful_cell_shutdown is not None:
            parameters['gracefulCellShutdown'] = graceful_cell_shutdown

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure("reset", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def reset_site(self, timeout=300, wait_for_reconnection=True, detailed_output=False, graceful_cell_shutdown=None, **kwargs):
        """
        Preform site reset procedure.

        :param int timeout: Timeout for the operation.
        :param bool wait_for_reconnection: True/False if we should wait for OAM Node-B reconnection
                    (Default: True, as in legacy siteReset admin-cli command).
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param bool graceful_cell_shutdown: (Optional) - Defaults to False, it is not applicable to ALD/GNSSE/GNSSI.
        :return str: Site reset status. Examples of returned statuses: "ongoing", "completed", "failed".

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """
        request_parameters = {"waitForReconnection": wait_for_reconnection, "resetCoverage": "Site"}
        if graceful_cell_shutdown is not None:
            request_parameters['gracefulCellShutdown'] = graceful_cell_shutdown
        response = self._api_client.execute_customer_procedure("reset", request_parameters, timeout)
        if response is None:
            raise DataNotAvailable("Site reset status has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

    def power_reset(self, reset_with_snapshot=None, wait_for_reconnection=None, timeout=1200, detailed_output=False,
                    cold_reset_secondary_core_via_backplane=None, graceful_cell_shutdown=None):
        """
        Power reset procedure introduced in CB007040 feature

        :param bool reset_with_snapshot: reset with snapshot (optional - default value: false)
        :param bool wait_for_reconnection: wait for reconnection (optional - default value: true)
        :param int timeout: timeout for procedure
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param bool cold_reset_secondary_core_via_backplane: (Optional) - Default value: False.
        :param bool graceful_cell_shutdown: (Optional) - Defaults to False, it is not applicable to ALD/GNSSE/GNSSI.
        :return dict: powerReset feedback

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-powerReset.html
        """
        parameters = {}
        if reset_with_snapshot is not None:
            parameters["resetWithSnapshot"] = reset_with_snapshot
        if wait_for_reconnection is not None:
            parameters["waitForReconnection"] = wait_for_reconnection
        if cold_reset_secondary_core_via_backplane is not None:
            parameters["coldResetSecondaryCoreViaBackplane"] = cold_reset_secondary_core_via_backplane
        if graceful_cell_shutdown is not None:
            parameters['gracefulCellShutdown'] = graceful_cell_shutdown
        response = self._api_client.execute_customer_procedure("powerReset", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

